1	import { fireEvent, render, screen } from '@testing-library/react';
2	import { describe, it, expect } from 'vitest';
3	import { MemoryRouter, Route, Routes } from 'react-router-dom';
4	import { TvStoreColumn } from './TvStoreColumn';
5	import type { TvStoreData } from '../model/types';
6	
7	const NOW = new Date(2026, 5, 4, 14, 30);
8	
9	const baseStore: TvStoreData = {
10	  lojaId: 5,
11	  nome: 'Momma Águas Claras',
12	  channel: 'degust-live',
13	  vendas: {
14	    valor: 8400,
15	    cupons: 184,
16	    ticketMedio: 38.5,
17	    dataReferencia: '2026-06-04',
18	    isLive: true,
19	    caixaAberto: true,
20	    atualizadoEm: '04/06/2026 14:28:35',
21	  },
22	  metaDia: 10_000,
23	  pctMeta: 120,
24	  deltaSemana: 6,
25	  deltaOntem: 4,
26	  estoque: { zerados: 0, abaixoMinimo: 0 },
27	  movimentacao: {
28	    entradas: 12,
29	    saidas: 8,
30	    ultimaBipagem: new Date(2026, 5, 4, 14, 21).toISOString(),
31	  },
32	  perdas: { valor: 120, itens: 3, deltaPct: null },
33	  marketing: { valor: 0, acoes: 0, deltaPct: null },
34	  criticalItems: [],
35	  recentMoves: [],
36	  rag: 'ok',
37	  ragReasons: [],
38	};
39	
40	function renderColumn(store: TvStoreData, now: Date = NOW) {
41	  return render(
42	    <MemoryRouter initialEntries={['/tv']}>
43	      <Routes>
44	        <Route
45	          path="/tv"
46	          element={<TvStoreColumn store={store} liveLevel="fresh" period="today" now={now} />}
47	        />
48	        <Route path="/tv/loja/:id" element={<div>detalhe-da-loja</div>} />
49	      </Routes>
50	    </MemoryRouter>,
51	  );
52	}
53	
54	describe('TvStoreColumn — estados RAG', () => {
55	  it('NEUTRO: sem chip de estado, vendas e delta vs ontem visíveis', () => {
56	    renderColumn(baseStore);
57	    const col = screen.getByTestId('tv-store-column');
58	    expect(col).toHaveAttribute('data-rag', 'ok');
59	    expect(screen.queryByText('atenção')).not.toBeInTheDocument();
60	    expect(screen.queryByText('crítico')).not.toBeInTheDocument();
61	    expect(screen.getByText('R$ 8.400,00')).toBeInTheDocument();
62	    // card tem 2 chips: deltaOntem (primeiro) + deltaSemana
63	    expect(screen.getAllByTestId('tv-delta-chip')[0]).toHaveTextContent('4% vs ontem');
64	    expect(screen.getByTestId('tv-col-bip')).toHaveTextContent('bip 14:21');
65	  });
66	
67	  it('ÂMBAR: chip atenção + frame âmbar', () => {
68	    renderColumn({ ...baseStore, rag: 'amber', ragReasons: ['3 itens abaixo do mínimo'] });
69	    expect(screen.getByTestId('tv-store-column')).toHaveAttribute('data-rag', 'amber');
70	    expect(screen.getByText('atenção')).toBeInTheDocument();
71	  });
72	
73	  it('VERMELHO: chip crítico + frame vermelho', () => {
74	    renderColumn({ ...baseStore, rag: 'red', ragReasons: ['2 itens zerados em alerta'] });
75	    expect(screen.getByTestId('tv-store-column')).toHaveAttribute('data-rag', 'red');
76	    expect(screen.getByText('crítico')).toBeInTheDocument();
77	  });
78	});
79	
80	describe('TvStoreColumn — status de estoque (linha única)', () => {
81	  it('sem alertas: mostra "estoque ok"', () => {
82	    renderColumn(baseStore);
83	    expect(screen.getByTestId('tv-col-stock-line')).toHaveTextContent('estoque ok');
84	  });
85	
86	  it('com zerados: mostra contagem + ícone', () => {
87	    renderColumn({ ...baseStore, estoque: { zerados: 2, abaixoMinimo: 1 } });
88	    expect(screen.getByTestId('tv-col-stock-line')).toHaveTextContent('2 zerados');
89	  });
90	
91	  it('só abaixo do mínimo: mostra contagem âmbar', () => {
92	    renderColumn({ ...baseStore, estoque: { zerados: 0, abaixoMinimo: 3 } });
93	    expect(screen.getByTestId('tv-col-stock-line')).toHaveTextContent('3 itens abaixo');
94	  });
95	});
96	
97	describe('TvStoreColumn — nome abreviado', () => {
98	  it('remove prefixo "Momma " do nome no card', () => {
99	    renderColumn(baseStore);
100	    expect(screen.getByRole('heading', { level: 2 })).toHaveTextContent('Águas Claras');
101	  });
102	});
103	
104	describe('TvStoreColumn — navegação para o drill-down', () => {
105	  it('clique na coluna navega para /tv/loja/:id', () => {
106	    renderColumn(baseStore);
107	    fireEvent.click(screen.getByTestId('tv-store-column'));
108	    expect(screen.getByText('detalhe-da-loja')).toBeInTheDocument();
109	  });
110	
111	  it('é acessível: role link com Enter navegando', () => {
112	    renderColumn(baseStore);
113	    const col = screen.getByRole('link', { name: 'Abrir detalhes de Momma Águas Claras' });
114	    fireEvent.keyDown(col, { key: 'Enter' });
115	    expect(screen.getByText('detalhe-da-loja')).toBeInTheDocument();
116	  });
117	});
118	
119	describe('TvStoreColumn — quebra Loja × Delivery (R1, BSB Shopping)', () => {
120	  it('mostra a linha discreta quando deliverySplit presente', () => {
121	    renderColumn({
122	      ...baseStore,
123	      deliverySplit: { delivery: 1074, balcao: 6668 },
124	    });
125	    const line = screen.getByTestId('tv-delivery-split');
126	    expect(line).toHaveTextContent('Loja');
127	    expect(line).toHaveTextContent('R$ 6.668,00');
128	    expect(line).toHaveTextContent('Delivery');
129	    expect(line).toHaveTextContent('R$ 1.074,00');
130	    // número principal segue sendo o TOTAL
131	    expect(screen.getByTestId('tv-store-sales')).toHaveTextContent('R$ 8.400,00');
132	  });
133	
134	  it('sem deliverySplit a linha não existe', () => {
135	    renderColumn(baseStore);
136	    expect(screen.queryByTestId('tv-delivery-split')).not.toBeInTheDocument();
137	  });
138	});
139	
140	describe('TvStoreColumn — meta do dia ausente', () => {
141	  it('sem metaDia: nenhum texto "sem meta" nem barra de meta no DOM', () => {
142	    renderColumn({ ...baseStore, metaDia: null, pctMeta: null });
143	    expect(screen.queryByText(/sem meta/i)).not.toBeInTheDocument();
144	    expect(screen.queryByTestId('tv-col-meta-bar')).not.toBeInTheDocument();
145	  });
146	});
147	
148	describe('TvStoreColumn — meta semanal (weeklyGoal)', () => {
149	  it('com weeklyGoal: label SEMANA + % + valores exatos + mini barra', () => {
150	    renderColumn({
151	      ...baseStore,
152	      weeklyGoal: { target: 374_500, achieved: 103_400, pct: 27.6 },
153	    });
154	    const block = screen.getByTestId('tv-weekly-goal');
155	    expect(block).toHaveTextContent('SEMANA');
156	    expect(screen.getByTestId('tv-weekly-goal-pct')).toHaveTextContent('28%');
157	    expect(block).toHaveTextContent('R$ 103.400,00 / R$ 374.500,00');
158	    expect(screen.getByTestId('tv-meta-bar')).toBeInTheDocument();
159	  });
160	
161	  it('meta batida (pct ≥ 100): % em emerald', () => {
162	    renderColumn({
163	      ...baseStore,
164	      weeklyGoal: { target: 10_000, achieved: 11_500, pct: 115 },
165	    });
166	    const pct = screen.getByTestId('tv-weekly-goal-pct');
167	    expect(pct).toHaveTextContent('115%');
168	    expect(pct.className).toContain('text-emerald-600');
169	  });
170	
171	  it('weeklyGoal null: nada da semana no DOM', () => {
172	    renderColumn({ ...baseStore, weeklyGoal: null });
173	    expect(screen.queryByTestId('tv-weekly-goal')).not.toBeInTheDocument();
174	    expect(screen.queryByText('SEMANA')).not.toBeInTheDocument();
175	  });
176	
177	  it('cor do % é PACE-ADJUSTED: terça no ritmo (~29% da semana) fica sage, não red', () => {
178	    // ter 02/06/2026 14:30 — esperado da semana = 2/7 ≈ 29%; realizado 28%
179	    // ⇒ ratio ≈ 0,98 → sage (antes: ratio 0,28 → vermelho ERRADO no início
180	    // de semana). O % numérico exibido segue sendo o real.
181	    const tuesday = new Date(2026, 5, 2, 14, 30);
182	    renderColumn(
183	      { ...baseStore, weeklyGoal: { target: 90_000, achieved: 25_700, pct: 28.6 } },
184	      tuesday,
185	    );
186	    const pct = screen.getByTestId('tv-weekly-goal-pct');
187	    expect(pct).toHaveTextContent('29%');
188	    expect(pct.className).toContain('text-[#57715B]');
189	    expect(pct.className).not.toContain('text-red-600');
190	  });
191	
192	  it('semana REALMENTE atrasada (ratio < 0,6 após 12h) fica vermelha', () => {
193	    // ter 02/06 14:30 — esperado ≈ 29%, realizado 10% ⇒ ratio ≈ 0,34 → red
194	    const tuesday = new Date(2026, 5, 2, 14, 30);
195	    renderColumn(
196	      { ...baseStore, weeklyGoal: { target: 90_000, achieved: 9_000, pct: 10 } },
197	      tuesday,
198	    );
199	    expect(screen.getByTestId('tv-weekly-goal-pct').className).toContain(
200	      'text-red-600',
201	    );
202	  });
203	
204	  it('mini barra mostra o tick dourado no esperado-agora da semana', () => {
205	    renderColumn({
206	      ...baseStore,
207	      weeklyGoal: { target: 374_500, achieved: 103_400, pct: 27.6 },
208	    });
209	    // NOW = qui 04/06 → esperado = 4/7 ≈ 57% (posição do tick)
210	    expect(screen.getByTestId('tv-meta-bar-tick')).toBeInTheDocument();
211	  });
212	});
213	
214	describe('TvStoreColumn — canal Linx defasado', () => {
215	  it('exibe delta vs dia anterior sem chip de fonte ao vivo', () => {
216	    renderColumn({
217	      ...baseStore,
218	      channel: 'linx-lagged',
219	      deltaOntem: -8,
220	      vendas: {
221	        valor: 4200,
222	        cupons: null,
223	        ticketMedio: null,
224	        dataReferencia: '2026-06-03',
225	        isLive: false,
226	        caixaAberto: null,
227	        atualizadoEm: null,
228	      },
229	    });
230	    expect(screen.getByText('R$ 4.200,00')).toBeInTheDocument();
231	    expect(screen.getAllByTestId('tv-delta-chip')[0]).toHaveTextContent('8% vs dia ant.');
232	  });
233	});
