1	/**
2	 * @module features/tv-dashboard/ui/TvStoreColumn
3	 *
4	 * Coluna vertical de loja — redesign baseado em research de TV dashboards
5	 * (Bach et al. IEEE TVCG 2023 + practitioner evidence):
6	 * - Número de vendas é o sinal primário → domina o espaço visualmente
7	 * - Máximo 5 elementos por card para não causar cognitive overload
8	 * - 1 RAG status por card (não 15 células coloridas)
9	 * - Detalhe de perdas/marketing/estoque → drill-down /tv/loja/:id
10	 */
11	
12	import { useEffect, useRef, useState } from 'react';
13	import { AlertTriangle, Bike } from 'lucide-react';
14	import type { TvFreshnessLevel, TvPeriod, TvStoreData } from '../model/types';
15	import {
16	  expectedWeekFraction,
17	  parseBrDateTime,
18	  parseIsoDateLocal,
19	  timeHHMMFromIso,
20	} from '../model/tvMath';
21	import { TvDeltaChip, TvLiveIndicator, TvMetaBar, TvRankChip, TvStateChip } from './TvChips';
22	import {
23	  TvColumnBipLine,
24	  TvColumnMetaBar,
25	  TvColumnStockLine,
26	  TvUnitColumn,
27	} from './TvColumnParts';
28	import {
29	  formatExactBRL,
30	  formatTicketBRL,
31	  formatWeekdayDayMonth,
32	  metaBarColorFromRatio,
33	  type TvBarColor,
34	} from './tvFormat';
35	import { useCountUp } from './useCountUp';
36	
37	interface TvStoreColumnProps {
38	  store: TvStoreData;
39	  liveLevel: TvFreshnessLevel;
40	  period: TvPeriod;
41	  now: Date;
42	  rank?: number | null;
43	}
44	
45	/** Coluna de loja — canal Degust live ou Linx defasado. */
46	export function TvStoreColumn({ store, liveLevel, period, now, rank }: TvStoreColumnProps) {
47	  const { vendas, channel } = store;
48	  const isLive = channel === 'degust-live';
49	  const valorAnim = useCountUp(vendas?.valor ?? 0);
50	  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;
51	
52	  // Flash dourado ao atualizar o valor de venda
53	  const prevValueRef = useRef(vendas?.valor);
54	  const [flashing, setFlashing] = useState(false);
55	  const flashKeyRef = useRef(0);
56	  useEffect(() => {
57	    if (
58	      vendas?.valor != null &&
59	      prevValueRef.current != null &&
60	      vendas.valor !== prevValueRef.current
61	    ) {
62	      flashKeyRef.current += 1;
63	      setFlashing(true);
64	      const t = window.setTimeout(() => setFlashing(false), 450);
65	      prevValueRef.current = vendas.valor;
66	      return () => window.clearTimeout(t);
67	    }
68	    prevValueRef.current = vendas?.valor;
69	  }, [vendas?.valor]);
70	
71	  // Linha de status: fonte + horário de atualização
72	  const updateTime = isLive ? parseBrDateTime(vendas?.atualizadoEm) : null;
73	  const laggedLabel = !isLive && refDate ? formatWeekdayDayMonth(refDate) : null;
74	
75	  const showRank = rank != null && rank >= 1 && rank <= 3;
76	
77	  return (
78	    <TvUnitColumn lojaId={store.lojaId} nome={store.nome} rag={store.rag} testId="tv-store-column">
79	
80	      {/* Header: nome + chips de status */}
81	      <div className="flex items-start justify-between gap-2">
82	        <h2 className="min-w-0 font-momma text-sm font-semibold leading-tight text-[#5F6F63] truncate">
83	          {store.nome.replace(/^Momma\s+/i, '')}
84	        </h2>
85	        <div className="flex shrink-0 items-center gap-1">
86	          {showRank && <TvRankChip rank={rank as 1 | 2 | 3} />}
87	          <TvStateChip rag={store.rag} />
88	        </div>
89	      </div>
90	
91	      {/* Número de vendas + setinhas inline — exatamente como na v2 */}
92	      <div className="mt-2 flex flex-wrap items-end gap-x-2 gap-y-1">
93	        <span
94	          key={flashing ? `flash-${flashKeyRef.current}` : 'static'}
95	          className={`font-momma text-[clamp(1.375rem,1.9vw,2.5rem)] font-bold leading-none tabular-nums ${
96	            vendas ? 'text-[#2D362E]' : 'text-[#9ca3af]'
97	          }${flashing ? ' tv-value-flash' : ''}`}
98	          data-testid="tv-store-sales"
99	        >
100	          {/* CountUp anima o número bruto; o EXATO é formatado a cada frame */}
101	          {vendas ? formatExactBRL(valorAnim) : '—'}
102	        </span>
103	        {store.deltaOntem != null && (
104	          <TvDeltaChip delta={store.deltaOntem} label={isLive ? 'ontem' : 'dia ant.'} size="card" />
105	        )}
106	        {store.deltaSemana != null && period === 'week' && (
107	          <TvDeltaChip delta={store.deltaSemana} label="sem. ant." size="card" />
108	        )}
109	      </div>
110	
111	      {/* R1: quebra Loja × Delivery (só BSB Shopping, período "hoje") —
112	          o número principal acima segue sendo o TOTAL oficial */}
113	      {store.deliverySplit && (
114	        <p
115	          className="mt-1 flex flex-wrap items-center gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]"
116	          data-testid="tv-delivery-split"
117	        >
118	          <span className="whitespace-nowrap">
119	            Loja{' '}
120	            <span className="font-medium text-[#5F6F63]">
121	              {formatExactBRL(store.deliverySplit.balcao)}
122	            </span>
123	          </span>
124	          <span aria-hidden>·</span>
125	          <span className="inline-flex items-center gap-1 whitespace-nowrap">
126	            <Bike className="h-3 w-3 shrink-0 text-[#57715B]" aria-hidden />
127	            Delivery{' '}
128	            <span className="font-medium text-[#5F6F63]">
129	              {formatExactBRL(store.deliverySplit.delivery)}
130	            </span>
131	          </span>
132	        </p>
133	      )}
134	
135	      {/* Status de fonte — compacto, sem "ao vivo" como texto */}
136	      {store.staleLive ? (
137	        <p className="mt-1 flex items-center gap-1.5 text-xs text-amber-600 dark:text-amber-500">
138	          <AlertTriangle className="h-3 w-3 shrink-0 text-amber-600 dark:text-amber-500" aria-hidden />
139	          {`sem sincronia desde ${timeHHMMFromIso(store.staleLive.since)}`}
140	        </p>
141	      ) : (
142	        <p className="mt-1 flex items-center gap-1.5 text-xs text-[#9ca3af]">
143	          <TvLiveIndicator channel={channel} liveLevel={liveLevel} />
144	          {isLive
145	            ? updateTime
146	              ? `${updateTime.getHours().toString().padStart(2, '0')}:${updateTime.getMinutes().toString().padStart(2, '0')}`
147	              : 'hoje'
148	            : laggedLabel ?? 'sem dados'}
149	        </p>
150	      )}
151	
152	      {/* Barra de meta do DIA */}
153	      <TvColumnMetaBar pctMetaProRata={store.pctMeta} metaDia={store.metaDia} now={now} />
154	
155	      {/* Meta da SEMANA corrente (seg–dom) — linha secundária, não compete
156	          com o número grande de vendas do dia. Ausente quando a loja não
157	          tem meta mensal cadastrada (weeklyGoal null/undefined). */}
158	      {store.weeklyGoal && (
159	        <TvStoreWeeklyGoalLine weeklyGoal={store.weeklyGoal} now={now} />
160	      )}
161	
162	      {/* Nº de vendas + R$/venda — cada parte non-breaking para não cortar */}
163	      {isLive && (vendas?.cupons != null || vendas?.ticketMedio != null) && (
164	        <div className="mt-2 flex flex-wrap items-baseline gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]">
165	          {vendas?.cupons != null && (
166	            <span className="whitespace-nowrap font-medium">
167	              {vendas.cupons} vendas
168	            </span>
169	          )}
170	          {vendas?.ticketMedio != null && vendas.ticketMedio > 0 && (
171	            <span className="whitespace-nowrap">
172	              {vendas.cupons != null && '· '}
173	              <span className="font-medium">{formatTicketBRL(vendas.ticketMedio)}</span>
174	              <span>/venda</span>
175	            </span>
176	          )}
177	        </div>
178	      )}
179	
180	      {/* Bip + Status de estoque — 1 linha para cada */}
181	      <div className="mt-auto pt-3 space-y-1">
182	        <TvColumnBipLine ultimaBipagem={store.movimentacao.ultimaBipagem} now={now} />
183	        <TvColumnStockLine estoque={store.estoque} />
184	      </div>
185	    </TvUnitColumn>
186	  );
187	}
188	
189	/** Cor do % da semana: emerald quando batida; senão mesma régua da barra. */
190	const WEEKLY_PCT_CLS: Record<TvBarColor, string> = {
191	  sage: 'text-[#57715B]',
192	  amber: 'text-amber-600',
193	  red: 'text-red-600',
194	};
195	
196	/**
197	 * Linha SECUNDÁRIA de meta semanal do card: label "SEMANA" + % em destaque
198	 * (cor pace-adjusted pela mesma régua da diária/mensal; emerald quando
199	 * ≥ 100%) + valores exatos "R$ X / R$ Y" + mini barra de progresso
200	 * ({@link TvMetaBar} mini com tick dourado no esperado-agora da semana).
201	 *
202	 * COR pace-adjusted: ratio = %real / %esperado-agora, com esperado =
203	 * dias decorridos ÷ dias do segmento seg-dom corrente do mês
204	 * ({@link expectedWeekFraction} — derivado localmente porque o
205	 * `weeklyGoal` do model não expõe o segmento). Começo de semana no ritmo
206	 * NÃO fica vermelho. O % NUMÉRICO exibido segue sendo o real.
207	 */
208	function TvStoreWeeklyGoalLine({
209	  weeklyGoal,
210	  now,
211	}: {
212	  weeklyGoal: NonNullable<TvStoreData['weeklyGoal']>;
213	  now: Date;
214	}) {
215	  const { target, achieved, pct } = weeklyGoal;
216	  const beaten = pct != null && pct >= 100;
217	  const expectedWeekPct = Math.round(expectedWeekFraction(now) * 100);
218	  const barColor: TvBarColor = beaten
219	    ? 'sage'
220	    : metaBarColorFromRatio(
221	        pct != null && expectedWeekPct > 0 ? pct / expectedWeekPct : null,
222	        now,
223	      );
224	  const pctCls = beaten ? 'text-emerald-600' : WEEKLY_PCT_CLS[barColor];
225	
226	  return (
227	    <div className="mt-2" data-testid="tv-weekly-goal">
228	      <div className="flex flex-wrap items-baseline justify-between gap-x-2 gap-y-0.5">
229	        <span className="font-momma text-[10px] font-semibold uppercase tracking-wider text-[#7C887E]">
230	          SEMANA
231	        </span>
232	        {/* Sem truncate: valor exato nunca pode ser cortado — quebra linha */}
233	        <span className="min-w-0 text-right font-momma text-[10px] tabular-nums text-[#9ca3af]">
234	          <span
235	            className={`text-xs font-bold tabular-nums ${pctCls}`}
236	            data-testid="tv-weekly-goal-pct"
237	          >
238	            {pct != null ? `${Math.round(pct)}%` : '—'}
239	          </span>{' '}
240	          {formatExactBRL(achieved)} / {formatExactBRL(target)}
241	        </span>
242	      </div>
243	      <div className="mt-1">
244	        <TvMetaBar
245	          fillPct={pct}
246	          expectedPct={pct != null ? expectedWeekPct : null}
247	          color={barColor}
248	          size="mini"
249	        />
250	      </div>
251	    </div>
252	  );
253	}
