1	import { createElement, type ReactNode } from 'react';
2	import { renderHook, waitFor } from '@testing-library/react';
3	import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
4	import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
5	import {
6	  TV_QUERY_INTERVALS,
7	  tvDashboardKeys,
8	  useTvDashboardData,
9	} from './useTvDashboardData';
10	import { businessTodayIso, currentWeekGoal, parseIsoDateLocal, TV_FLASH_STALE_MINUTES } from './tvMath';
11	
12	// Estado mutável dos mocks (hoisted: a factory do vi.mock roda antes do
13	// corpo do arquivo). Por default: tabelas vazias e edge fora do ar (503) —
