describe('TvStoreColumn — staleLive (A2/R3)', () => {
  // ISO sem timezone → interpretado como horário LOCAL → getHours()=2, getMinutes()=25
  // O mesmo ISO é o que o hook grava em TvStoreData.staleLive.since.
  const STALE_SINCE = '2026-06-04T02:25:00';

  it('(a) renderiza texto âmbar "sem sincronia desde HH:mm"', () => {
    const storeStale: TvStoreData = {
      ...baseStore,
      staleLive: { since: STALE_SINCE },
    };
    renderColumn(storeStale);
    // timeHHMMFromIso('2026-06-04T02:25:00') → "02:25" (local, sem Z)
    expect(
      screen.getByText('sem sincronia desde 02:25'),
    ).toBeInTheDocument();
  });

  it('(b) NÃO renderiza o indicador "ao vivo" (pulso verde) no ramo stale', () => {
    const storeStale: TvStoreData = {
      ...baseStore,
      staleLive: { since: STALE_SINCE },
    };
    renderColumn(storeStale);
    // TvLiveIndicator: span com aria-label="ao vivo" — ausente no ramo stale
    expect(screen.queryByLabelText('ao vivo')).not.toBeInTheDocument();
  });

  it('(c) o número de vendas (tv-store-sales) permanece visível no ramo stale', () => {
    const storeStale: TvStoreData = {
      ...baseStore,
      staleLive: { since: STALE_SINCE },
    };
    renderColumn(storeStale);
    expect(screen.getByTestId('tv-store-sales')).toBeInTheDocument();
    // valor numérico continua sendo exibido (não é ocultado)
    expect(screen.getByTestId('tv-store-sales')).toHaveTextContent('R$ 8.400,00');
  });

  it('(d) ramo normal (staleLive null): TvLiveIndicator presente, sem texto âmbar', () => {
    // Garante que o ramo não-stale não regrediu
    const storeNormal: TvStoreData = { ...baseStore, staleLive: null };
    renderColumn(storeNormal);
    // dot "ao vivo" presente (liveLevel="fresh", canal degust-live)
    expect(screen.getByLabelText('ao vivo')).toBeInTheDocument();
    expect(
      screen.queryByText(/sem sincronia desde/),
    ).not.toBeInTheDocument();
  });
});

